/**
 * Centralized job lifecycle manager for module generation.
 *
 * This module is the SINGLE OWNER of:
 * - Job submission
 * - Queue polling
 * - Job status polling
 * - Module creation from completed jobs
 * - Task status updates
 *
 * Other modules (ai_action.js, queue_status.js) should use this manager
 * and listen to events rather than polling directly.
 *
 * Events dispatched:
 * - job-queued: {queueId, status} - Job submitted and queued
 * - job-processing: {queueId, jobId} - Job started processing
 * - job-completed: {queueId, cmid, sectionid, sectionnumber, beforemod} - Module created successfully
 * - job-failed: {queueId, error} - Job failed
 *
 * @module     block_dixeo_modulegen/job_manager
 * @copyright  2026 Edunao SAS (contact@edunao.com)
 * @author     Josemaria Bolanos <admin@mako.digital>
 * @author     Pierre FACQ <pierre.facq@edunao.com>
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define([
    'local_dixeo/network',
    'block_dixeo_modulegen/connection'
], function(Network, Connection) {
    'use strict';

    /** @var {number} Initial delay before first job poll (AI generation takes time). */
    const INITIAL_JOB_POLL_DELAY_MS = 30000;

    /** @var {number} Polling interval for job status after initial delay. */
    const JOB_POLL_INTERVAL_MS = 5000;

    /** @var {number} Polling interval for queue status. */
    const QUEUE_POLL_INTERVAL_MS = 5000;

    /** @var {number} Maximum polling attempts before timeout (~10 min at 5s intervals). */
    const MAX_POLL_ATTEMPTS = 120;

    /**
     * @var {number} Minimum delay between module creation calls after one was lost on the network.
     * Longer than the server's 60 s creation lock wait, so a busy reply arrives before the next call.
     */
    const CREATE_RECHECK_MS = 90000;

    /**
     * Job state object structure.
     * @typedef {Object} JobState
     * @property {string|null} jobId - The Dixeo job UUID (null if queued).
     * @property {string} status - Current status: queued, processing, completed, failed.
     * @property {number} attempts - Number of polling attempts.
     * @property {Object} args - Original submission arguments.
     * @property {number|null} timeoutId - Active setTimeout ID for polling.
     * @property {Object|undefined} retryWindow - Connection failures of this job's polling.
     * @property {number|null|undefined} createLost - Time a module creation call was lost on the network.
     * @property {number|undefined} lastCreateAt - Time of the last module creation call.
     * @property {Object|undefined} createStall - Watches the queue row after a lost creation call.
     */

    /** @var {Map<number, JobState>} activeJobs - Map of queueId to job state. */
    const activeJobs = new Map();

    /** @var {number|null} courseId - The current course ID. */
    let courseId = null;

    /** @var {boolean} initialized - Whether the manager has been initialized. */
    let initialized = false;

    /** @var {number|null} queuePollTimeoutId - Active queue polling timeout. */
    let queuePollTimeoutId = null;

    /** @var {Object|null} lastQueueData - Cached queue status data. */
    let lastQueueData = null;

    /** @var {number} lastQueueFetchTime - Timestamp of last queue fetch. */
    let lastQueueFetchTime = 0;

    /** @var {Promise|null} pendingQueueFetch - In-flight queue fetch promise. */
    let pendingQueueFetch = null;

    /** @var {number} QUEUE_CACHE_TTL_MS - Cache validity duration (2 seconds). */
    const QUEUE_CACHE_TTL_MS = 2000;

    /** @var {boolean} visibilityListenerAttached - Whether the visibility change listener is attached. */
    let visibilityListenerAttached = false;

    /** @var {Object} queueRetryWindow - Connection failures of the queue polling. */
    const queueRetryWindow = Network.createRetryWindow();

    /** @var {boolean} connectionNoticeShown - Whether the connection message was shown on this page. */
    let connectionNoticeShown = false;

    /**
     * Show the connection message once per page, however many jobs lost their polling.
     */
    const notifyConnectionOnce = () => {
        if (connectionNoticeShown) {
            return;
        }
        connectionNoticeShown = true;
        Connection.notifyConnection();
    };

    /**
     * The retry window of a job's polling, created on first use.
     *
     * @param {Object} job
     * @returns {Object}
     */
    const jobRetryWindow = (job) => {
        if (!job.retryWindow) {
            job.retryWindow = Network.createRetryWindow();
        }
        return job.retryWindow;
    };

    /**
     * Handle visibility change events.
     *
     * When the browser tab becomes visible again after being hidden (e.g., user switched tabs),
     * immediately resume polling for any active jobs. This handles browser tab suspension
     * where timers are throttled or paused while the tab is inactive.
     */
    const handleVisibilityChange = () => {
        if (document.visibilityState !== 'visible') {
            return;
        }

        // Invalidate cache so next fetch gets fresh data.
        lastQueueFetchTime = 0;

        // Resume polling for any processing jobs immediately.
        activeJobs.forEach((job, queueId) => {
            if (job.status === 'processing' && job.jobId) {
                // Clear any pending timeout and poll immediately.
                if (job.timeoutId) {
                    clearTimeout(job.timeoutId);
                    job.timeoutId = null;
                }
                pollJobStatus(queueId);
            }
        });

        // Resume queue polling if we have queued jobs.
        let hasQueuedJobs = false;
        activeJobs.forEach((job) => {
            if (job.status === 'queued') {
                hasQueuedJobs = true;
            }
        });

        if (hasQueuedJobs) {
            if (queuePollTimeoutId) {
                clearTimeout(queuePollTimeoutId);
                queuePollTimeoutId = null;
            }
            pollQueueStatus();
        }
    };

    /**
     * Dispatch a custom event with job data.
     *
     * @param {string} eventName - The event name (without 'job-' prefix).
     * @param {Object} detail - Event detail data.
     */
    const dispatchJobEvent = (eventName, detail) => {
        document.dispatchEvent(new CustomEvent('job-' + eventName, {detail: detail}));
    };

    /**
     * Build mod/view.php link for a created activity.
     *
     * @param {string} modulename
     * @param {number} cmid
     * @returns {string|null}
     */
    const buildActivityLink = (modulename, cmid) => {
        if (!cmid || !modulename) {
            return null;
        }
        return M.cfg.wwwroot + '/mod/' + modulename + '/view.php?id=' + cmid;
    };

    /**
     * Dispatch job-completed with queue task metadata when available.
     *
     * The detail repeats the task's beforemod (the module the new one was
     * inserted before, 0 for end of section) so listeners refreshing their
     * own rendering of the section know where the activity landed.
     *
     * @param {number} queueId
     * @param {Object} job
     * @param {number} cmid
     * @param {number} sectionid Target course section id.
     * @param {number|null} sectionnumber Number of the section the module landed in, null when unknown.
     */
    const dispatchCompletionEvent = (queueId, job, cmid, sectionid, sectionnumber) => {
        const detail = {
            queueId: queueId,
            cmid: cmid,
            sectionid: sectionid,
            sectionnumber: sectionnumber,
            beforemod: parseInt(job.args.beforemod, 10) || 0,
            queuemode: job.queuemode || 'generate',
            courseid: job.args.courseid || courseId,
            modulename: job.args.modulename || '',
            displaytitle: job.displaytitle || '',
            link: buildActivityLink(job.args.modulename, cmid),
        };

        fetchQueueStatus(true).then((data) => {
            if (data.tasks && Array.isArray(data.tasks)) {
                const task = data.tasks.find((t) => t.id === queueId);
                if (task) {
                    detail.queuemode = task.queuemode || detail.queuemode;
                    if (task.link) {
                        detail.link = task.link;
                    }
                    if (task.displaytitle) {
                        detail.displaytitle = task.displaytitle;
                    }
                }
            }
            dispatchJobEvent('completed', detail);
            return undefined;
        }).catch(() => {
            dispatchJobEvent('completed', detail);
            return undefined;
        });
    };

    /**
     * Dispatch job-failed with queue metadata.
     *
     * @param {number} queueId
     * @param {Object|null} job
     * @param {string} error
     */
    const dispatchFailureEvent = (queueId, job, error) => {
        dispatchJobEvent('failed', {
            queueId: queueId,
            error: error,
            queuemode: job && job.queuemode ? job.queuemode : 'generate',
            courseid: job && job.args ? (job.args.courseid || courseId) : courseId,
            modulename: job && job.args ? (job.args.modulename || '') : '',
        });
    };

    /**
     * Update a task status via the API.
     *
     * @param {number} queueId - The queue record ID.
     * @param {string} action - The action: fail or cancel.
     * @param {number} cmid - Ignored by the server.
     * @param {string} errorMsg - Ignored by the server.
     * @param {string} [jobId] - Job UUID required for fail correlation.
     * @returns {Promise} Resolves when update completes.
     */
    const updateTask = (queueId, action, cmid, errorMsg, jobId) => {
        if (!queueId) {
            return Promise.resolve();
        }

        return Network.call({
            methodname: 'block_dixeo_modulegen_update_task',
            args: {
                queueid: queueId,
                action: action,
                cmid: cmid || 0,
                error: errorMsg || '',
                jobid: jobId || ''
            }
        }, {timeout: Network.TIMEOUT_ACTION_MS}).catch((failure) => {
            // A cancel the user asked for reports a lost connection; anything else is silent.
            if (action === 'cancel' && Network.isConnectionError(failure)) {
                throw failure;
            }
            return undefined;
        });
    };

    /**
     * Delete a task (remove from queue or from display).
     *
     * @param {number} queueId - The queue record ID.
     * @returns {Promise<Object>} Resolves with {success, message}.
     */
    const deleteTask = (queueId) => {
        if (!queueId) {
            return Promise.reject(new Error('Queue ID required'));
        }
        activeJobs.delete(queueId);
        return Network.call({
            methodname: 'block_dixeo_modulegen_delete_task',
            args: {queueid: queueId}
        }, {timeout: Network.TIMEOUT_ACTION_MS}).then((result) => {
            if (!result.success) {
                const message = result.message || 'Failed to remove task';
                throw new Error(message);
            }
            return result;
        });
    };

    /**
     * Create the module from a completed job.
     *
     * The server endpoint is idempotent: it re-checks the queue row under a
     * lock, creates the module only if it has not been created yet, and marks
     * the row complete/failed itself. Concurrent callers (other tabs, pages)
     * get the already-created cmid back instead of creating a duplicate.
     *
     * The call is never resent automatically: a lost call is followed through the queue row
     * (see followLostCreate).
     *
     * @param {number} queueId - The queue record ID.
     * @returns {Promise<{cmid: number, sectionid: number, sectionnumber: number}>} Created module and placement.
     */
    const createModuleFromJob = (queueId) => {
        return Network.call({
            methodname: 'block_dixeo_modulegen_create_module_for_task',
            args: {queueid: queueId}
        }, {timeout: Network.TIMEOUT_ACTION_MS}).then((result) => {
            if (!result.success) {
                const error = new Error(result.message || 'Failed to create module');
                error.retry = !!result.retry;
                throw error;
            }
            return {
                cmid: result.cmid,
                sectionid: result.sectionid || 0,
                sectionnumber: result.sectionnumber || 0,
            };
        });
    };

    /**
     * Schedule the next poll of a job.
     *
     * @param {number} queueId
     * @param {Object} job
     */
    const scheduleJobPoll = (queueId, job) => {
        job.timeoutId = setTimeout(() => pollJobStatus(queueId), JOB_POLL_INTERVAL_MS);
    };

    /**
     * Stop polling a job after a lasting connection loss, without failing it.
     *
     * The server job keeps running and the queue resumes it on the next page load.
     *
     * @param {number} queueId
     * @param {Object} job
     */
    const stopWithoutFailing = (queueId, job) => {
        if (job.timeoutId) {
            clearTimeout(job.timeoutId);
            job.timeoutId = null;
        }
        activeJobs.delete(queueId);
        notifyConnectionOnce();
    };

    /**
     * Report a module created for a job and stop tracking it.
     *
     * @param {number} queueId
     * @param {Object} job
     * @param {{cmid: number, sectionid: number, sectionnumber: number}} result
     */
    const completeJob = (queueId, job, result) => {
        job.status = 'completed';
        job.createLost = null;
        dispatchCompletionEvent(queueId, job, result.cmid, result.sectionid, result.sectionnumber);
        activeJobs.delete(queueId);
    };

    /**
     * Report a job whose module could not be created and stop tracking it.
     *
     * @param {number} queueId
     * @param {Object} job
     * @param {string} message
     */
    const failCreate = (queueId, job, message) => {
        job.status = 'failed';
        job.createLost = null;
        dispatchFailureEvent(queueId, job, message);
        activeJobs.delete(queueId);
    };

    /**
     * Ask the server to create the module of a completed job.
     *
     * After a creation call is lost on the network, the job enters the lost-create state: its
     * queue row is read on each tick instead of the job status, and a reply without success
     * and without retry is not final, because it is the busy reply of the creation lock while
     * the first call is still creating the module.
     *
     * @param {number} queueId
     * @param {Object} job
     * @returns {Promise<void>}
     */
    const runCreate = async(queueId, job) => {
        job.status = 'creating';
        job.lastCreateAt = Date.now();
        try {
            const result = await createModuleFromJob(queueId);
            if (activeJobs.has(queueId)) {
                completeJob(queueId, job, result);
            }
        } catch (error) {
            if (!activeJobs.has(queueId)) {
                return;
            }
            if (Network.isConnectionError(error)) {
                if (!job.createLost) {
                    job.createLost = Date.now();
                    job.createStall = Network.createStallWatch({
                        startMs: Network.STALL_PROGRESS_MS,
                        stallMs: Network.STALL_PROGRESS_MS,
                    });
                }
                job.status = 'processing';
                if (!jobRetryWindow(job).shouldRetry(error)) {
                    stopWithoutFailing(queueId, job);
                    return;
                }
                scheduleJobPoll(queueId, job);
                return;
            }
            if (error.retry || (job.createLost && !error.errorcode)) {
                // The server could not read the job yet, or the lost call is still creating
                // the module: read again on the next tick.
                job.status = 'processing';
                scheduleJobPoll(queueId, job);
                return;
            }
            failCreate(queueId, job, error.message);
        }
    };

    /**
     * Read the queue row of a job whose module creation call was lost, and act on it.
     *
     * @param {number} queueId
     * @param {Object} job
     * @returns {Promise<void>}
     */
    const readLostCreate = async(queueId, job) => {
        let data;
        try {
            data = await fetchQueueStatus(true);
        } catch (error) {
            if (!activeJobs.has(queueId)) {
                return;
            }
            const keepReading = Network.isConnectionError(error)
                ? jobRetryWindow(job).shouldRetry(error)
                : true;
            if (!keepReading || job.createStall.stalled()) {
                stopWithoutFailing(queueId, job);
                return;
            }
            scheduleJobPoll(queueId, job);
            return;
        }
        if (!activeJobs.has(queueId)) {
            return;
        }
        jobRetryWindow(job).succeeded();

        const task = Array.isArray(data.tasks) ? data.tasks.find((t) => t.id === queueId) : null;
        if (!task) {
            // Task not found - may have been deleted.
            job.createLost = null;
            activeJobs.delete(queueId);
            return;
        }
        const status = parseInt(task.status, 10);
        job.createStall.observe(String(status), true);

        // STATUS_COMPLETED = 2: a confirming call returns the created module and its placement.
        if (status === 2 && task.cmid) {
            await runCreate(queueId, job);
            return;
        }
        // STATUS_FAILED = 3, STATUS_CANCELLED = 4
        if (status === 3 || status === 4) {
            failCreate(queueId, job, status === 4 ? 'Task was cancelled' : (task.statuslabel || 'Task failed'));
            return;
        }
        if (job.createStall.stalled()) {
            stopWithoutFailing(queueId, job);
            return;
        }
        // STATUS_PROCESSING = 1: a fresh creation call is idempotent on the server.
        if (status === 1 && Date.now() - (job.lastCreateAt || 0) >= CREATE_RECHECK_MS) {
            await runCreate(queueId, job);
            return;
        }
        scheduleJobPoll(queueId, job);
    };

    /**
     * Follow a job whose module creation call was lost, through its queue row.
     * Only one read runs at a time for a job.
     *
     * @param {number} queueId
     * @param {Object} job
     * @returns {Promise<void>}
     */
    const followLostCreate = async(queueId, job) => {
        if (job.lostReadPending) {
            return;
        }
        job.lostReadPending = true;
        try {
            await readLostCreate(queueId, job);
        } finally {
            job.lostReadPending = false;
        }
    };

    /**
     * Poll job status until completion.
     *
     * Connection failures are retried within the job's retry window and do not count as
     * polling attempts. Past the window, polling of the job stops without failing it.
     *
     * @param {number} queueId - The queue record ID.
     */
    const pollJobStatus = async(queueId) => {
        const job = activeJobs.get(queueId);
        if (!job || !job.jobId) {
            return;
        }

        if (job.createLost) {
            await followLostCreate(queueId, job);
            return;
        }

        job.attempts++;

        if (job.attempts > MAX_POLL_ATTEMPTS) {
            job.status = 'failed';
            updateTask(queueId, 'fail', 0, 'Generation timed out', job.jobId);
            dispatchFailureEvent(queueId, job, 'Generation timed out');
            activeJobs.delete(queueId);
            return;
        }

        let status;
        try {
            status = await Network.call({
                methodname: 'local_dixeo_get_job_status',
                args: {
                    jobid: job.jobId,
                    courseid: job.args.courseid || courseId,
                }
            }, {timeout: Network.TIMEOUT_STATUS_MS});
        } catch (error) {
            if (!activeJobs.has(queueId)) {
                return;
            }
            if (Network.isConnectionError(error)) {
                job.attempts--;
                if (jobRetryWindow(job).shouldRetry(error)) {
                    scheduleJobPoll(queueId, job);
                    return;
                }
                stopWithoutFailing(queueId, job);
                return;
            }
            job.status = 'failed';
            updateTask(queueId, 'fail', 0, error.message || 'Polling error', job.jobId);
            dispatchFailureEvent(queueId, job, error.message || 'Polling error');
            activeJobs.delete(queueId);
            return;
        }

        // Job may have been cancelled while polling.
        if (!activeJobs.has(queueId)) {
            return;
        }
        jobRetryWindow(job).succeeded();

        if (status.status === 'completed') {
            // Guard against overlapping polls in this tab (e.g. a visibility
            // re-poll firing while a create request is already in flight).
            if (job.status === 'creating') {
                return;
            }
            await runCreate(queueId, job);
            return;
        }

        if (status.status === 'failed') {
            const errorMsg = status.error?.detail || 'Generation failed';
            job.status = 'failed';
            updateTask(queueId, 'fail', 0, errorMsg, job.jobId);
            dispatchFailureEvent(queueId, job, errorMsg);
            activeJobs.delete(queueId);
            return;
        }

        // Still processing - schedule next poll.
        scheduleJobPoll(queueId, job);
    };

    /**
     * Start job polling with initial delay.
     *
     * @param {number} queueId - The queue record ID.
     * @param {boolean} immediate - If true, start polling immediately (for resumed jobs).
     */
    const startJobPolling = (queueId, immediate = false) => {
        const job = activeJobs.get(queueId);
        if (!job) {
            return;
        }

        const delay = immediate ? 0 : INITIAL_JOB_POLL_DELAY_MS;
        job.timeoutId = setTimeout(() => pollJobStatus(queueId), delay);
    };

    /**
     * Fetch queue status with caching and deduplication.
     * This is the single point for all queue status API calls.
     *
     * @param {boolean} forceRefresh - If true, bypass cache.
     * @returns {Promise<Object>} The queue status data.
     */
    const fetchQueueStatus = (forceRefresh = false) => {
        if (!courseId) {
            return Promise.resolve({tasks: [], stats: {queued: 0, processing: 0, completed: 0}});
        }

        const now = Date.now();

        // Return cached data if still valid.
        if (!forceRefresh && lastQueueData && (now - lastQueueFetchTime) < QUEUE_CACHE_TTL_MS) {
            return Promise.resolve(lastQueueData);
        }

        // Return pending request if one is in flight.
        if (pendingQueueFetch) {
            return pendingQueueFetch;
        }

        // Make new request.
        pendingQueueFetch = Network.call({
            methodname: 'block_dixeo_modulegen_get_queue_status',
            args: {courseid: courseId}
        }, {timeout: Network.TIMEOUT_STATUS_MS}).then((data) => {
            lastQueueData = data;
            lastQueueFetchTime = Date.now();
            pendingQueueFetch = null;

            // Dispatch event so UI modules can update.
            dispatchJobEvent('queue-data', {data: data});

            return data;
        }).catch((error) => {
            pendingQueueFetch = null;
            throw error;
        });

        return pendingQueueFetch;
    };

    /**
     * Poll queue status to track job progression.
     * This handles jobs transitioning from queued to processing.
     *
     * Connection failures are retried within the retry window; past it, polling stops and the
     * connection message is shown once.
     */
    const pollQueueStatus = () => {
        if (!courseId) {
            return;
        }

        // Check if we have any jobs in 'queued' state that need monitoring.
        let hasQueuedJobs = false;
        activeJobs.forEach((job) => {
            if (job.status === 'queued') {
                hasQueuedJobs = true;
            }
        });

        if (!hasQueuedJobs) {
            queuePollTimeoutId = null;
            return;
        }

        fetchQueueStatus(true).then((data) => {
            queueRetryWindow.succeeded();
            if (!data.tasks || !Array.isArray(data.tasks)) {
                return undefined;
            }

            // Check each of our tracked queued jobs.
            activeJobs.forEach((job, queueId) => {
                if (job.status !== 'queued') {
                    return;
                }

                const task = data.tasks.find(t => t.id === queueId);
                if (!task) {
                    // Task not found - may have been deleted.
                    activeJobs.delete(queueId);
                    return;
                }

                const status = parseInt(task.status);

                // STATUS_PROCESSING = 1
                if (status === 1 && task.jobid) {
                    job.status = 'processing';
                    job.jobId = task.jobid;
                    job.attempts = 0;
                    dispatchJobEvent('processing', {queueId: queueId, jobId: task.jobid});
                    startJobPolling(queueId, false);
                    return;
                }

                // STATUS_COMPLETED = 2 (completed by another client/cron).
                if (status === 2) {
                    job.status = 'completed';
                    dispatchCompletionEvent(queueId, job, task.cmid || 0, job.args.sectionid, null);
                    activeJobs.delete(queueId);
                    return;
                }

                // STATUS_FAILED = 3, STATUS_CANCELLED = 4
                if (status === 3 || status === 4) {
                    job.status = 'failed';
                    const errorMsg = status === 4 ? 'Task was cancelled' : 'Task failed';
                    dispatchFailureEvent(queueId, job, errorMsg);
                    activeJobs.delete(queueId);
                }
            });

            // Continue polling if we still have queued jobs.
            let stillHasQueued = false;
            activeJobs.forEach((job) => {
                if (job.status === 'queued') {
                    stillHasQueued = true;
                }
            });

            if (stillHasQueued) {
                queuePollTimeoutId = setTimeout(pollQueueStatus, QUEUE_POLL_INTERVAL_MS);
            } else {
                queuePollTimeoutId = null;
            }

            return undefined;
        }).catch((failure) => {
            if (Network.isConnectionError(failure) && !queueRetryWindow.shouldRetry(failure)) {
                queuePollTimeoutId = null;
                notifyConnectionOnce();
                return undefined;
            }
            // Retry on error.
            queuePollTimeoutId = setTimeout(pollQueueStatus, QUEUE_POLL_INTERVAL_MS);
            return undefined;
        });
    };

    /**
     * Start queue polling if not already running.
     */
    const ensureQueuePolling = () => {
        if (queuePollTimeoutId === null) {
            pollQueueStatus();
        }
    };

    /**
     * Resume polling for PROCESSING jobs found on page load.
     * This handles browser refresh during an active generation.
     * Uses task record fields (instructions, sectionid, beforemod) for job args.
     *
     * @param {Array} tasks - Array of task objects from get_queue_status API.
     */
    const resumeProcessingJobs = (tasks) => {
        if (!tasks || !Array.isArray(tasks)) {
            return;
        }

        tasks.forEach((task) => {
            const status = parseInt(task.status);
            const queueId = task.id;

            // Only resume jobs we're not already tracking.
            if (activeJobs.has(queueId)) {
                return;
            }

            // STATUS_PROCESSING = 1
            if (status === 1 && task.jobid) {
                activeJobs.set(queueId, {
                    jobId: task.jobid,
                    status: 'processing',
                    attempts: 0,
                    queuemode: task.queuemode || 'generate',
                    displaytitle: task.displaytitle || '',
                    args: {
                        courseid: courseId,
                        modulename: task.modulename,
                        instructions: task.instructions || '',
                        sectionid: task.sectionid || 0,
                        beforemod: task.beforemod || 0
                    },
                    timeoutId: null
                });

                dispatchJobEvent('processing', {queueId: queueId, jobId: task.jobid});
                // Resume immediately - job is already in progress.
                startJobPolling(queueId, true);
            }

            // STATUS_PENDING = 0, or PROCESSING claimed by the queue before the job id is known.
            if (status === 0 || (status === 1 && !task.jobid)) {
                if (task.queuemode === 'fill' || task.queuemode === 'manual') {
                    return;
                }
                activeJobs.set(queueId, {
                    jobId: null,
                    status: 'queued',
                    attempts: 0,
                    queuemode: task.queuemode || 'generate',
                    displaytitle: task.displaytitle || '',
                    args: {
                        courseid: courseId,
                        modulename: task.modulename,
                        instructions: task.instructions || '',
                        sectionid: task.sectionid || 0,
                        beforemod: task.beforemod || 0
                    },
                    timeoutId: null
                });

                ensureQueuePolling();
            }
        });
    };

    return {
        /**
         * Initialize the job manager.
         *
         * Must be called before using any other methods.
         * Fetches current queue state and resumes polling for active jobs.
         * The read is retried through short connection losses.
         *
         * @param {number} cid - The course ID.
         * @returns {Promise} Resolves when initialization is complete.
         */
        init: function(cid) {
            if (initialized && courseId === cid) {
                return Promise.resolve();
            }

            courseId = cid;

            // Attach visibility change listener to handle browser tab suspension.
            if (!visibilityListenerAttached) {
                document.addEventListener('visibilitychange', handleVisibilityChange);
                visibilityListenerAttached = true;
            }

            return Network.retryRead(() => fetchQueueStatus(true)).then((data) => {
                initialized = true;
                if (data.tasks) {
                    resumeProcessingJobs(data.tasks);
                }
                return undefined;
            }).catch((error) => {
                // Mark as initialized anyway so new jobs work.
                initialized = true;
                // eslint-disable-next-line no-console
                console.warn('JobManager init failed after retries:', error);
                return undefined;
            });
        },

        /**
         * Get queue status data.
         *
         * Uses cached data if available and fresh, otherwise fetches from API.
         * This is the single point for queue status access - UI modules should
         * use this instead of direct Ajax calls.
         *
         * @param {boolean} forceRefresh - If true, bypass cache and fetch fresh data.
         * @returns {Promise<Object>} The queue status data with tasks and stats.
         */
        getQueueStatus: function(forceRefresh = false) {
            return fetchQueueStatus(forceRefresh);
        },

        /**
         * Start following the processing and queued tasks of a queue read that are not tracked yet.
         *
         * @param {Array} tasks - Array of task objects from get_queue_status API.
         */
        resumeJobs: function(tasks) {
            resumeProcessingJobs(tasks);
        },

        /**
         * Submit a new job for module generation.
         *
         * @param {Object} args - Submission arguments.
         * @param {number} args.courseid - The course ID.
         * @param {string} args.modulename - The module type (page, quiz, etc.).
         * @param {string} args.instructions - User instructions for generation.
         * @param {number} args.sectionid - Target course section id.
         * @param {number} args.beforemod - Module ID to insert before (0 for end).
         * @returns {Promise<{queueId: number, status: string}>} Resolves with queue info. Rejects with a
         *     connection error when the answer was lost: the job may have been queued anyway.
         */
        submitJob: function(args) {
            // A paid start: sent once.
            return Network.call({
                methodname: 'block_dixeo_modulegen_submit_generation',
                args: args
            }, {timeout: Network.TIMEOUT_ACTION_MS}).then((data) => {
                if (!data.success) {
                    const message = data.error?.message || 'Failed to submit generation';
                    throw new Error(message);
                }

                const queueId = data.queueid;
                const jobId = data.jobid || null;
                const status = data.status;

                // Track this job.
                activeJobs.set(queueId, {
                    jobId: jobId,
                    status: status,
                    attempts: 0,
                    queuemode: 'generate',
                    displaytitle: '',
                    args: args,
                    timeoutId: null
                });

                // Dispatch appropriate event.
                if (status === 'processing' && jobId) {
                    dispatchJobEvent('processing', {queueId: queueId, jobId: jobId});
                    startJobPolling(queueId, false);
                } else {
                    dispatchJobEvent('queued', {queueId: queueId, status: status});
                    ensureQueuePolling();
                }

                return {queueId: queueId, status: status};
            });
        },

        /**
         * Cancel an active job.
         *
         * @param {number} queueId - The queue record ID.
         * @returns {Promise} Resolves when cancellation is complete.
         */
        cancelJob: function(queueId) {
            const job = activeJobs.get(queueId);

            if (job && job.timeoutId) {
                clearTimeout(job.timeoutId);
            }

            activeJobs.delete(queueId);

            return updateTask(queueId, 'cancel', 0, '');
        },

        /**
         * Remove a task from the queue (delete from database).
         * Allowed for queued, completed, failed, cancelled. Not for processing.
         *
         * @param {number} queueId - The queue record ID.
         * @returns {Promise<Object>} Resolves with {success, message}.
         */
        removeTask: function(queueId) {
            return deleteTask(queueId);
        },

        /**
         * Get all currently tracked jobs.
         *
         * @returns {Map<number, JobState>} Map of queueId to job state.
         */
        getActiveJobs: function() {
            return new Map(activeJobs);
        },

        /**
         * Check if a job is being tracked.
         *
         * @param {number} queueId - The queue record ID.
         * @returns {boolean} True if the job is being tracked.
         */
        isTracking: function(queueId) {
            return activeJobs.has(queueId);
        },

        /**
         * Get the course ID.
         *
         * @returns {number|null} The course ID or null if not initialized.
         */
        getCourseId: function() {
            return courseId;
        }
    };
});
